css:
body {
     font-family: Arial, sans-serif;
     font-size: 13px;
     color: #000;
     margin: 15px;
   }
   .header, .footer {
     text-align: center;
     margin-bottom: 10px;
   }
   .header img, .footer img {
     max-height: 100px;
   }
   h2, h3 {
     text-align: center;
     margin: 2px 0;
   }
   .sub-title {
     text-align: center;
     font-size: 11px;
     margin-bottom: 8px;
   }
   table {
     width: 100%;
     border-collapse: collapse;
     margin-top: 8px;
   }
   th, td {
     border: 1px solid #444;
     padding: 4px 6px;
     text-align: left;
   }
   th {
     background-color: #f2f2f2;
     font-size: 11px;
   }
   td {
     font-size: 13px;
   }
   .info {
     border: 1px solid #444;
     margin-top: 10px;
   }

   .info td {
     border: 1px solid #444;
     padding: 6px 8px;
     font-size: 11px;
   }

   .totals td {
     border: none;
     font-weight: bold;
     padding: 4px 6px;
   }
   .signatures td {
     border: none;
     padding: 25px 10px 5px;
     text-align: center;
     font-size: 11px;
   }
   .section-title {
     margin-top: 15px;
     font-weight: bold;
     font-size: 11px;
     text-decoration: underline;
   }
